/* ludcmp.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"

/* ---------------------------------------------------------------------------
 * Small helper macro: tell GCC/Clang that a pointer is 64‑byte aligned.
 * PolyBench typically allocates arrays with at least this alignment, so this
 * does not change semantics but gives the optimizer better information.
 * On non-GNU compilers it degrades to a no-op cast.
 * --------------------------------------------------------------------------- */
#if defined(__GNUC__)
#  define ASSUME_ALIGNED_64(ptr) __builtin_assume_aligned((ptr), 64)
#else
#  define ASSUME_ALIGNED_64(ptr) (ptr)
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Create local, potentially restrict-qualified row/1D views.
   * This reduces address arithmetic and helps the compiler reason
   * about aliasing. We keep all accesses in the same order, so
   * floating‑point semantics are preserved. */
  DATA_TYPE (*restrict A_)[n] = (DATA_TYPE (*)[n])A;
  DATA_TYPE *restrict b_      = b;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;

  for (i = 0; i < n; i++)
    {
      x_[i] = 0;
      y_[i] = 0;
      b_[i] = (i+1)/fn/2.0 + 4;
    }

  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A_[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;

      for (j = i+1; j < n; j++) {
	Ai[j] = 0;
      }

      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite.
   * (Not required for LU, but kept identical to the original algorithm
   * used in Cholesky so that the benchmark's behavior is unchanged.)
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*restrict B_)[n] = (DATA_TYPE (*)[n])POLYBENCH_ARRAY(B);

  /* Initialize B to zero. */
  for (r = 0; r < n; ++r) {
    DATA_TYPE *restrict Br = B_[r];
    for (s = 0; s < n; ++s)
      Br[s] = 0;
  }

  /* Compute B = A * A^T.
   *
   * Original code:
   *   for (t)
   *     for (r)
   *       for (s)
   *         B[r][s] += A[r][t] * A[s][t];
   *
   * Here we keep the same loop ordering with respect to t (the reduction
   * dimension) to preserve the sequence of floating‑point operations
   * contributing to each B[r][s].  We only introduce a row pointer and
   * hoist A[r][t] into a temporary to reduce redundant loads and index
   * computations.
   */
  for (t = 0; t < n; ++t)
    {
      for (r = 0; r < n; ++r)
        {
          const DATA_TYPE A_rt = A_[r][t];
          DATA_TYPE *restrict Br = B_[r];

          for (s = 0; s < n; ++s)
            Br[s] += A_rt * A_[s][t];
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict Ar = A_[r];
      DATA_TYPE *restrict Br = B_[r];

      for (s = 0; s < n; ++s)
	Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

  /* Use the PolyBench run-time bound (may differ from the compile-time N). */
  const int nn = _PB_N;

  /* Local, restrict-qualified, aligned views of the arrays.
   *  - ASSUME_ALIGNED_64 tells the compiler that the base pointers are
   *    at least 64‑byte aligned, matching PolyBench's default behavior.
   *  - The restrict qualifiers communicate that A, b, x, and y do not
   *    alias one another, which is true for this benchmark.
   * We then use these views exclusively inside the kernel.
   */
  DATA_TYPE (*restrict A_)[n] =
    (DATA_TYPE (*)[n])ASSUME_ALIGNED_64(A);
  DATA_TYPE *restrict b_ =
    (DATA_TYPE *)ASSUME_ALIGNED_64(b);
  DATA_TYPE *restrict x_ =
    (DATA_TYPE *)ASSUME_ALIGNED_64(x);
  DATA_TYPE *restrict y_ =
    (DATA_TYPE *)ASSUME_ALIGNED_64(y);

#pragma scop
  /* LU factorization without pivoting.
   *
   * We keep the original loop nesting and iteration space so the
   * order of floating‑point operations is unchanged.  The main
   * optimizations are:
   *  - Use row pointers (Ai) to avoid repeated base+index arithmetic.
   *  - Manually unroll the innermost k loops by a factor of 4.
   *    The unrolling is written so that the updates to 'w' occur in
   *    exactly the same order as in the original scalar loop, thus
   *    preserving numerical behavior while reducing loop overhead.
   */
  for (i = 0; i < nn; i++) {
    DATA_TYPE *restrict Ai = A_[i];

    /* Compute strict lower-triangular entries (L part). */
    for (j = 0; j < i; j++) {
       w = Ai[j];

       /* Inner product: w -= sum_{k=0}^{j-1} A[i][k] * A[k][j] */
       int k_unrolled_end = (j / 4) * 4;
       for (k = 0; k < k_unrolled_end; k += 4) {
          /* The four updates below correspond exactly to k, k+1, k+2, k+3
             iterations of the original scalar loop. */
          w -= Ai[k]   * A_[k  ][j];
          w -= Ai[k+1] * A_[k+1][j];
          w -= Ai[k+2] * A_[k+2][j];
          w -= Ai[k+3] * A_[k+3][j];
       }
       for (; k < j; k++) {
          w -= Ai[k] * A_[k][j];
       }

       Ai[j] = w / A_[j][j];
    }

    /* Compute diagonal and upper-triangular entries (U part). */
    for (j = i; j < nn; j++) {
       w = Ai[j];

       /* Inner product: w -= sum_{k=0}^{i-1} A[i][k] * A[k][j] */
       int k_unrolled_end = (i / 4) * 4;
       for (k = 0; k < k_unrolled_end; k += 4) {
          w -= Ai[k]   * A_[k  ][j];
          w -= Ai[k+1] * A_[k+1][j];
          w -= Ai[k+2] * A_[k+2][j];
          w -= Ai[k+3] * A_[k+3][j];
       }
       for (; k < i; k++) {
          w -= Ai[k] * A_[k][j];
       }

       Ai[j] = w;
    }
  }

  /* Forward substitution: solve L * y = b. */
  for (i = 0; i < nn; i++) {
     DATA_TYPE *restrict Ai = A_[i];
     w = b_[i];
     for (j = 0; j < i; j++)
        w -= Ai[j] * y_[j];
     y_[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (i = nn-1; i >= 0; i--) {
     DATA_TYPE *restrict Ai = A_[i];
     w = y_[i];
     for (j = i+1; j < nn; j++)
        w -= Ai[j] * x_[j];
     x_[i] = w / Ai[i];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_ludcmp (n,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(b),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(b);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
