 * Contact:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* ludcmp.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stddef.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"

/* Tunable blocking factors for the initialization GEMM-like phase.
 * These can be overridden at compile time, e.g.:
 *   -DLUDCMP_INIT_BLOCK_R=64 -DLUDCMP_INIT_BLOCK_S=64
 */
#ifndef LUDCMP_INIT_BLOCK_R
# define LUDCMP_INIT_BLOCK_R 32
#endif

#ifndef LUDCMP_INIT_BLOCK_S
# define LUDCMP_INIT_BLOCK_S 32
#endif


/* Array initialization. */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
                 DATA_TYPE POLYBENCH_1D(b,N,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n),
                 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Local restrict-qualified aliases to help the compiler with alias analysis. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict b_ = b;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict y_ = y;

  /* Initialize vectors x, y and the right-hand side b. */
  for (i = 0; i < n; i++)
    {
      x_[i] = (DATA_TYPE)0;
      y_[i] = (DATA_TYPE)0;
      b_[i] = (DATA_TYPE)(i + 1) / fn / (DATA_TYPE)2.0 + (DATA_TYPE)4.0;
    }

  /* Initialize A as a unit lower-triangular-like matrix. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict A_i = A_[i];

      for (j = 0; j <= i; j++)
        A_i[j] = (DATA_TYPE)(-j % n) / fn + (DATA_TYPE)1.0;

      for (j = i + 1; j < n; j++)
        A_i[j] = (DATA_TYPE)0;

      A_i[i] = (DATA_TYPE)1.0;
    }

  /* Make the matrix positive semi-definite.
   * This is effectively computing B = A * A^T and then copying B back to A.
   * We keep the outer-most loop on 't' to preserve the exact accumulation
   * order per element, but use blocking in (r,s) to improve cache locality.
   * This does not change the sequence of updates applied to each A[r][s].
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Zero-initialize B in a cache-friendly way.  Using memset is safe here
   * because the storage for B is contiguous and a zero byte pattern
   * represents +0.0 for the DATA_TYPE used in PolyBench.
   */
  memset(B_, 0, (size_t)n * (size_t)n * sizeof(DATA_TYPE));

  const int r_block = LUDCMP_INIT_BLOCK_R;
  const int s_block = LUDCMP_INIT_BLOCK_S;

  /* B[r][s] += A[r][t] * A[s][t]  (with t as the outer-most loop). */
  for (t = 0; t < n; ++t)
    {
      for (r = 0; r < n; r += r_block)
        {
          int r_end = r + r_block;
          if (r_end > n)
            r_end = n;

          for (s = 0; s < n; s += s_block)
            {
              int s_end = s + s_block;
              if (s_end > n)
                s_end = n;

              for (int rr = r; rr < r_end; ++rr)
                {
                  const DATA_TYPE A_rt = A_[rr][t];
                  DATA_TYPE *restrict B_rr = B_[rr];

                  for (int ss = s; ss < s_end; ++ss)
                    {
                      /* Same update as original: one contribution for (rr,ss,t). */
                      B_rr[ss] += A_rt * A_[ss][t];
                    }
                }
            }
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
