/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
                   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
                   DATA_TYPE POLYBENCH_1D(b,N,n),
                   DATA_TYPE POLYBENCH_1D(x,N,n),
                   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

  /* Local restrict-qualified aliases to give the compiler stronger
   * guarantees about aliasing and enable better vectorization and
   * scheduling.
   */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict b_ = b;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict y_ = y;

  /* Use the PolyBench loop bound macro as a single runtime value,
   * which may expand to N (compile-time) or n (runtime) depending
   * on configuration.
   */
  const int n_pb = _PB_N;

  /* Temporary buffer for computing the U part of each row i.
   * Sized with n_pb so that we never access out of bounds, regardless
   * of how _PB_N is defined.
   */
  DATA_TYPE tmp_U[n_pb];

#pragma scop
  /* LU factorization without pivoting: A = L*U, L unit lower-triangular. */
  for (i = 0; i < n_pb; i++) {
    DATA_TYPE *restrict A_i = A_[i];

    /* Compute L(i, j) for j < i:
     *   L(i,j) = (A(i,j) - sum_{k=0..j-1} L(i,k)*U(k,j)) / U(j,j)
     */
    for (j = 0; j < i; j++) {
      w = A_i[j];

      /* Dot product over k < j. No loop-carried dependencies in k. */
      for (k = 0; k < j; k++) {
        const DATA_TYPE *restrict A_k = A_[k];
        w -= A_i[k] * A_k[j];
      }

      /* Division by the U diagonal element, as in the original code. */
      A_i[j] = w / A_[j][j];
    }

    /* Compute U(i, j) for j >= i:
     *   U(i,j) = A(i,j) - sum_{k=0..i-1} L(i,k)*U(k,j)
     *
     * Instead of computing each U(i,j) independently with j outermost,
     * we:
     *   1. Copy the current row segment A(i, j>=i) into tmp_U.
     *   2. For each k < i, update all tmp_U[j] in a single inner loop.
     *   3. Copy tmp_U back to A(i, j>=i).
     *
     * For each fixed j, the sequence of operations on that element
     * (initial value, then k = 0..i-1 updates) is identical to the
     * original code; we only change the interleaving across different j's.
     */
    for (j = i; j < n_pb; j++) {
      tmp_U[j] = A_i[j];
    }

    for (k = 0; k < i; k++) {
      const DATA_TYPE aik = A_i[k];                /* L(i,k) */
      const DATA_TYPE *restrict A_k = A_[k];       /* Row k provides U(k, j) */

      for (j = i; j < n_pb; j++) {
        tmp_U[j] -= aik * A_k[j];
      }
    }

    for (j = i; j < n_pb; j++) {
      A_i[j] = tmp_U[j];
    }
  }

  /* Forward substitution: solve L * y = b. */
  for (i = 0; i < n_pb; i++) {
    const DATA_TYPE *restrict A_i = A_[i];
    w = b_[i];

    for (j = 0; j < i; j++)
      w -= A_i[j] * y_[j];

    y_[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (i = n_pb - 1; i >= 0; i--) {
    const DATA_TYPE *restrict A_i = A_[i];
    w = y_[i];

    for (j = i + 1; j < n_pb; j++)
      w -= A_i[j] * x_[j];

    x_[i] = w / A_i[i];
  }
#pragma endscop

}


