      for (t = 0; t < n; ++t)
        sum_rr += Ar[t] * Ar[t];
      Br[r] = sum_rr;

      /* Upper triangle: s > r. Compute B[r][s] and mirror to B[s][r]. */
      for (s = r + 1; s < n; ++s)
