  for (i = 0; i < N_; i++) {
     const DATA_TYPE *restrict Ai = A_[i];
     w = b_[i];
     for (j = 0; j < i; j++)
        w -= Ai[j] * y_[j];
     y_[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (i = N_-1; i >= 0; i--) {
     const DATA_TYPE *restrict Ai = A_[i];
     w = y_[i];
     for (j = i+1; j < N_; j++)
        w -= Ai[j] * x_[j];
     x_[i] = w / Ai[i];
  }
