     for (j = 0; j < i; j++)
        w -= Ai[j] * y_[j];
     y_[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (i = n_pb-1; i >= 0; i--) {
     DATA_TYPE * restrict Ai = A_[i];
     w = y_[i];
     for (j = i+1; j < n_pb; j++)
        w -= Ai[j] * x_[j];
     x_[i] = w / Ai[i];
  }
#pragma endscop

}


